mapper.select:
select msg.message_id, p.post_no, coalesce(nullif(sender.nickname, ''), nullif(sender.legal_subject_name, ''), sender.member_code, '未知商户') as from_merchant_name, coalesce(nullif(receiver.nickname, ''), nullif(receiver.legal_subject_name, ''), receiver.member_code, '未知商户') as to_merchant_name, msg.message_content, msg.read_flag, msg.risk_flag, date_format(msg.create_time, '%Y-%m-%d %H:%i:%s') as create_time from ry_rental.ry_rental_market_message msg inner join ry_rental.ry_rental_market_post p on p.post_id = msg.post_id and p.is_delete = 0 left join ry_rental.ry_rental_member sender on sender.member_id = msg.from_member_id and sender.is_delete = 0 left join ry_rental.ry_rental_member receiver on receiver.member_id = msg.to_member_id and receiver.is_delete = 0 where msg.is_delete = 0 and (msg.from_member_id = #{memberId} or msg.to_member_id = #{memberId}) and msg.read_flag = #{readFlag}
and (p.post_no like concat('%', #{keyword}, '%') or msg.message_content like concat('%', #{keyword}, '%') or sender.nickname like concat('%', #{keyword}, '%') or receiver.nickname like concat('%', #{keyword}, '%'))
order by msg.create_time desc, msg.message_id desc
